#!/usr/bin/env python3
"""A standalone terminal viewer for folded stack profiles.

The parser, navigation model, terminal layout, and renderer are independent of
any external profiling or terminal UI package.
"""
import errno
import functools
import math
import os
import re
import select
import signal
import struct
import sys
import termios
import time
import unicodedata

MASK = (1 << 64) - 1
VERSION = 'flamelens 0.3.1'


def usage(prog):
    return f'Usage: {prog} [OPTIONS] [FILENAME]'


def help_text(prog):
    return (usage(prog) + '\n\nArguments:\n'
            '  [FILENAME]  Profile data filename\n\nOptions:\n'
            '      --sorted   Whether to sort the stacks by time spent\n'
            '      --echo     Print data to stdout on exit. Useful when piping to other tools\n'
            '      --debug    Show debug info\n'
            '  -h, --help     Print help\n'
            '  -V, --version  Print version\n')


def similarity(a, b):
    """Jaro similarity for short option spelling suggestions."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    distance = max(len(a), len(b)) // 2 - 1
    distance = max(distance, 0)
    am = [False] * len(a)
    bm = [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i-distance), min(len(b), i+distance+1)):
            if not bm[j] and c == b[j]:
                am[i] = bm[j] = True
                break
    m = sum(am)
    if not m:
        return 0.0
    aa = [c for c, ok in zip(a, am) if ok]
    bb = [c for c, ok in zip(b, bm) if ok]
    transpositions = sum(x != y for x, y in zip(aa, bb)) / 2
    return (m/len(a) + m/len(b) + (m-transpositions)/m) / 3


def arguments(argv):
    prog = os.path.basename(argv[0]) or 'executable'
    filename = None
    flags = set()
    positional = False
    known = ('--sorted', '--echo', '--debug', '--help', '--version')

    def error(message, tip='', custom_usage=None):
        text = 'error: ' + message + '\n\n'
        if tip:
            text += '  tip: ' + tip + '\n\n'
        text += (custom_usage or usage(prog)) + "\n\nFor more information, try '--help'.\n"
        sys.stderr.write(text)
        raise SystemExit(2)

    for arg in argv[1:]:
        if positional:
            if filename is not None:
                error(f"unexpected argument '{arg}' found")
            filename = arg
            continue
        if arg == '--':
            positional = True
            continue
        if arg.startswith('--'):
            name, sep, value = arg.partition('=')
            if name in known:
                if sep:
                    error(f"unexpected value '{value}' for '{name}' found; no more were expected",
                          custom_usage=f'Usage: {prog} {name} [FILENAME]')
                if name == '--help':
                    sys.stdout.write(help_text(prog))
                    raise SystemExit(0)
                if name == '--version':
                    print(VERSION)
                    raise SystemExit(0)
                if name in flags:
                    error(f"the argument '{name}' cannot be used multiple times")
                flags.add(name)
                continue
            scores = [(similarity(name[2:], x[2:]), x) for x in known]
            score, candidate = max(scores)
            if score > 0.8:
                error(f"unexpected argument '{name}' found",
                      f"a similar argument exists: '{candidate}'",
                      f'Usage: {prog} <FILENAME|--sorted|--echo|--debug>')
            error(f"unexpected argument '{name}' found",
                  f"to pass '{name}' as a value, use '-- {name}'")
        if arg.startswith('-') and arg != '-':
            for ch in arg[1:]:
                if ch == 'h':
                    sys.stdout.write(help_text(prog))
                    raise SystemExit(0)
                if ch == 'V':
                    print(VERSION)
                    raise SystemExit(0)
                error(f"unexpected argument '-{ch}' found",
                      f"to pass '-{ch}' as a value, use '-- -{ch}'")
        if filename is not None:
            error(f"unexpected argument '{arg}' found")
        filename = arg
    return filename, flags


def rust_os_error(exc):
    kinds = {2: 'NotFound', 13: 'PermissionDenied', 21: 'IsADirectory',
             11: 'WouldBlock', 20: 'NotADirectory', 22: 'InvalidInput',
             36: 'InvalidFilename', 40: 'FilesystemLoop', 9: 'Uncategorized'}
    code = exc.errno or 5
    message = os.strerror(code)
    return f'Os {{ code: {code}, kind: {kinds.get(code, "Uncategorized")}, message: "{message}" }}'


def panic(location, message):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/main.rs:{location}:\n"
                     + message + '\n'
                     + 'note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')
    raise SystemExit(101)


def read_profile(filename):
    if filename is not None:
        try:
            with open(filename, 'rb') as f:
                raw = f.read()
        except OSError as e:
            panic('44:47', 'Could not read file: ' + rust_os_error(e))
        try:
            return raw.decode('utf-8')
        except UnicodeDecodeError:
            panic('44:47', 'Could not read file: Error { kind: InvalidData, message: "stream did not contain valid UTF-8" }')
    try:
        raw = sys.stdin.buffer.read()
    except OSError as e:
        panic('49:10', 'Could not read stdin: ' + rust_os_error(e))
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError as e:
        errlen = 'None' if e.reason == 'unexpected end of data' else f'Some({e.end-e.start})'
        message = ('Could not parse stdin: FromUtf8Error { bytes: ['
                   + ', '.join(str(x) for x in raw) + '], error: Utf8Error { valid_up_to: '
                   + str(e.start) + ', error_len: ' + errlen + ' } }')
        panic('51:46', message)


@functools.lru_cache(maxsize=32768)
def stable_hash(text):
    """64-bit, fixed-key SipHash-1-3 of a delimited UTF-8 string."""
    data = text.encode('utf-8') + b'\xff'
    v = [0x736f6d6570736575, 0x646f72616e646f6d,
         0x6c7967656e657261, 0x7465646279746573]

    def rotate(n, b):
        return ((n << b) | (n >> (64-b))) & MASK

    def mix():
        v[0] = (v[0] + v[1]) & MASK
        v[1] = rotate(v[1], 13) ^ v[0]
        v[0] = rotate(v[0], 32)
        v[2] = (v[2] + v[3]) & MASK
        v[3] = rotate(v[3], 16) ^ v[2]
        v[0] = (v[0] + v[3]) & MASK
        v[3] = rotate(v[3], 21) ^ v[0]
        v[2] = (v[2] + v[1]) & MASK
        v[1] = rotate(v[1], 17) ^ v[2]
        v[2] = rotate(v[2], 32)

    stop = len(data) // 8 * 8
    for i in range(0, stop, 8):
        block = int.from_bytes(data[i:i+8], 'little')
        v[3] ^= block
        mix()
        v[0] ^= block
    block = ((len(data) & 255) << 56) | int.from_bytes(data[stop:], 'little')
    v[3] ^= block
    mix()
    v[0] ^= block
    v[2] ^= 255
    mix()
    mix()
    mix()
    return v[0] ^ v[1] ^ v[2] ^ v[3]


@functools.lru_cache(maxsize=32768)
def heat_color(path):
    value = stable_hash(path) / MASK
    return (int(205 + 50*value), int(230*value), int(55*value))


def text_color(bg):
    brightness = .2126*bg[0] + .7152*bg[1] + .0722*bg[2]
    return (10, 10, 10) if brightness >= 128 else (225, 225, 225)


class Frame:
    __slots__ = ('name', 'path', 'parent', 'depth', 'count', 'own', 'children', 'lookup', 'index')

    def __init__(self, name, path, parent, index):
        self.name = name
        self.path = path
        self.parent = parent
        self.depth = parent.depth + 1 if parent is not None else 0
        self.count = 0
        self.own = 0
        self.children = []
        self.lookup = {}
        self.index = index


class Profile:
    def __init__(self, data, sorted_stacks=False):
        self.root = Frame('all', 'all', None, 0)
        self.frames = [self.root]
        self.functions = {}
        self.records = []
        for line in data.split('\n'):
            if ' ' not in line:
                continue
            path, count_text = line.rsplit(' ', 1)
            if not path or not re.fullmatch(r'\+?[0-9]+', count_text):
                continue
            try:
                count = int(count_text)
            except (ValueError, OverflowError):
                continue
            if count > MASK:
                continue
            names = path.split(';')
            self.records.append((tuple(names), count))
            current = self.root
            current.count = (current.count + count) & MASK
            prefixes = []
            for name in names:
                prefixes.append(name)
                if name not in current.lookup:
                    node = Frame(name, ';'.join(prefixes), current, len(self.frames))
                    current.children.append(node)
                    current.lookup[name] = node
                    self.frames.append(node)
                current = current.lookup[name]
                current.count = (current.count + count) & MASK
            current.own = (current.own + count) & MASK
            for name in set(names):
                stats = self.functions.setdefault(name, [0, 0])
                stats[0] = (stats[0] + count) & MASK
            stats = self.functions[names[-1]]
            stats[1] = (stats[1] + count) & MASK
        if sorted_stacks:
            for frame in self.frames:
                frame.children = list(reversed(sorted(frame.children, key=lambda n: n.count)))


# Terminal styles are (foreground, background, bold, reverse). A color may be
# None, an ANSI palette index, or an RGB tuple.
DEFAULT = (None, None, False, False)
BOLD = (None, None, True, False)
ACCENT = (3, None, True, False)
RED = (225, 10, 10)
SELECT_BG = (250, 250, 250)
MATCH_BG = (10, 35, 150)
ROW_BG = (65, 65, 65)


def char_width(ch):
    n = ord(ch)
    if ch in ('\u200d', '\ufe0f', '\ufe0e') or unicodedata.combining(ch):
        return 0
    if n < 32 or 0x7f <= n < 0xa0:
        return 0
    return 2 if unicodedata.east_asian_width(ch) in ('F', 'W') else 1


def glyphs(text):
    """Yield display clusters and their source offsets."""
    i = 0
    while i < len(text):
        start = i
        ch = text[i]
        i += 1
        width = char_width(ch)
        while i < len(text):
            if text[i] == '\u200d' and i + 1 < len(text):
                i += 2
                width = max(width, char_width(text[i-1]))
            elif char_width(text[i]) == 0 and ord(text[i]) >= 32:
                if text[i] == '\ufe0f':
                    width = max(width, 2)
                i += 1
            else:
                break
        if width > 0:
            yield text[start:i], width, start, i


def display_width(text):
    return sum(w for _, w, _, _ in glyphs(text))


def clipped(text, width):
    result = []
    used = 0
    for s, w, _, _ in glyphs(text):
        if used + w > width:
            break
        result.append(s)
        used += w
    return ''.join(result)


def wrap_text(text, width):
    if width <= 0:
        return ['']
    lines = []
    for paragraph in text.split('\n'):
        tokens = re.findall(r'\S+|[^\S\n]+', paragraph)
        current = ''
        size = 0
        pending = ''
        for token in tokens:
            if token.isspace():
                pending += token
                continue
            tw = display_width(token)
            pw = display_width(pending) if current else 0
            if size + pw + tw <= width:
                if current:
                    current += pending
                    size += pw
                current += token
                size += tw
            else:
                if current:
                    lines.append(current)
                    current = ''
                    size = 0
                for c, cw, _, _ in glyphs(token):
                    if size + cw > width:
                        lines.append(current)
                        current = ''
                        size = 0
                    current += c
                    size += cw
            pending = ''
        lines.append(current)
    return lines or ['']


class Canvas:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.rows = [[(' ', DEFAULT) for _ in range(width)] for _ in range(height)]

    def fill(self, x, y, width, style=DEFAULT, char=' '):
        if 0 <= y < self.height:
            for col in range(max(0, x), min(self.width, x+width)):
                self.rows[y][col] = (char, style)

    def text(self, x, y, text, style=DEFAULT, limit=None, highlights=()):
        if not 0 <= y < self.height:
            return
        end = self.width if limit is None else min(self.width, x+max(0, limit))
        for ch, cw, start, stop in glyphs(text):
            if x+cw > end:
                break
            use_style = style
            if any(a < stop and b > start for a, b in highlights):
                use_style = (RED, style[1], True, style[3])
            if x >= 0:
                self.rows[y][x] = (ch, use_style)
                if cw == 2 and x+1 < self.width:
                    self.rows[y][x+1] = ('', use_style)
            x += cw

    def spans(self, x, y, spans):
        for text, style in spans:
            self.text(x, y, text, style)
            x += display_width(text)

    def border(self, y, title=None):
        self.fill(0, y, self.width, char='─')
        if title:
            self.text(0, y, title + ' ', ACCENT)


def percentage(count, total):
    if not total:
        return 'NaN' if not count else 'inf'
    return f'{float(count) / float(total) * 100:.2f}'


def regex_escape(text):
    return re.sub(r'([\\.*+?()\[\]{}^$|#&~\-])', r'\\\1', text)


def compile_regex(pattern):
    # The profile search grammar intentionally excludes backreferences and
    # look-around assertions, which cannot be evaluated as regular languages.
    if re.search(r'(?<!\\)(?:\\[1-9]|\(\?(?:[=!]|<[=!])))', pattern):
        raise ValueError('unsupported regex expression')
    p = pattern.replace(r'\z', r'\Z')
    p = p.replace(r'\p{ASCII}', r'[\x00-\x7f]')
    p = p.replace(r'\p{Greek}', '[\u0370-\u03ff\u1f00-\u1fff]')
    p = p.replace(r'\p{L}', '[^\W\d_]')
    p = p.replace(r'\p{Letter}', '[^\W\d_]')
    p = p.replace(r'\p{N}', r'\d')
    return re.compile(p)


class Viewer:
    def __init__(self, profile, title, debug=False):
        self.profile = profile
        self.title = title
        self.debug = debug
        self.top = False
        self.selected = profile.root
        self.zoom = None
        self.scroll = 0
        self.sort_own = True
        self.table_index = 0
        self.table_scroll = 0
        self.pattern = None
        self.regex = None
        self.matches = {}
        self.match_count = 0
        self.editing = False
        self.input_text = ''
        self.input_cursor = 0
        self.input_scroll = 0
        self.info = None
        self.width = 80
        self.height = 24
        self.body_height = 17
        self.body_y = 3
        self.placed = {}
        self.levels = {}
        self.order = []
        self.max_depth = 0
        self.ancestors = set()
        self.rows = []
        self.keep_running = True
        self.cursor = None
        self.refresh_rows()

    def refresh_rows(self):
        rows = [(name, counts[0], counts[1]) for name, counts in self.profile.functions.items()
                if self.regex is None or self.regex.search(name) is not None]
        col = 2 if self.sort_own else 1
        rows.sort(key=lambda row: (row[col], row[0]), reverse=True)
        self.rows = rows
        self.table_index = min(self.table_index, max(0, len(rows)-1))
        self.table_scroll = min(self.table_scroll, max(0, len(rows)-1))

    def set_pattern(self, pattern):
        if not pattern:
            self.pattern = self.regex = None
            self.matches = {}
            self.match_count = 0
            self.info = None
            self.refresh_rows()
            return
        try:
            compiled = compile_regex(pattern)
        except (ValueError, re.error, OverflowError):
            self.info = 'Invalid regex: ' + pattern
            return
        self.pattern = pattern
        self.regex = compiled
        self.info = None
        self.matches = {}
        for name in self.profile.functions:
            self.matches[name] = [(m.start(), m.end()) for m in compiled.finditer(name)]
        self.match_count = sum(count for names, count in self.profile.records
                               if any(self.matches.get(name) for name in names)) & MASK
        self.refresh_rows()

    def reset(self):
        self.selected = self.profile.root
        self.zoom = None
        self.scroll = 0
        self.sort_own = True
        self.table_index = self.table_scroll = 0
        self.set_pattern(None)
        self.info = None

    def sample_text(self, name, count):
        value = f'{name} [{count} samples, {percentage(count, self.profile.root.count)}% of all'
        if self.zoom is not None:
            value += f', {percentage(count, self.zoom.count)}% of zoomed'
        return value + ']'

    def panels(self):
        if self.editing:
            return [('Search', [''])]
        panels = []
        if self.pattern is not None:
            panels.append(('Match', wrap_text(self.sample_text('"'+self.pattern+'"', self.match_count), self.width)))
        if not self.top:
            panels.append(('Selected', wrap_text(self.sample_text(self.selected.name, self.selected.count), self.width)))
        if self.debug:
            text = 'Debug: render:0.02ms handle_key_events:0.00ms flamegraph:0.02ms'
            panels.append(('Debug', wrap_text(text, self.width)))
        if self.info:
            panels.append(('Info', wrap_text(self.info, self.width)))
        return panels

    def place_frames(self):
        root = self.profile.root
        scale_count = self.zoom.count if self.zoom is not None else root.count
        scale = self.width / float(scale_count) if scale_count else 0
        self.ancestors = set()
        path = {}
        if self.zoom is not None:
            child = self.zoom
            while child.parent is not None:
                self.ancestors.add(child.parent)
                path[child.parent] = child
                child = child.parent
        placed = {}
        levels = {}
        pending = [(root, 0, self.width)]
        while pending:
            node, x, width = pending.pop()
            if width <= 0:
                continue
            placed[node] = (x, width)
            levels.setdefault(node.depth, []).append(node)
            if node in path:
                pending.append((path[node], 0, self.width))
                continue
            next_nodes = []
            for child in node.children:
                value = float(child.count) * scale
                cw = min(65535, max(0, int(value)))
                next_nodes.append((child, x, cw))
                x = (x + cw) & 65535
            pending.extend(reversed(next_nodes))
        self.placed = placed
        self.levels = levels
        self.max_depth = max(levels, default=0)
        self.order = [node for depth in sorted(levels) for node in levels[depth]]
        if self.selected not in placed:
            parent = self.selected
            while parent not in placed and parent.parent:
                parent = parent.parent
            self.selected = parent

    def ensure_cursor(self):
        capacity = max(1, self.body_height)
        maximum = max(0, self.max_depth+1-capacity)
        self.scroll = min(maximum, max(0, self.scroll))
        if self.selected.depth < self.scroll:
            self.scroll = self.selected.depth
        elif self.selected.depth >= self.scroll + capacity:
            self.scroll = self.selected.depth - capacity + 1
        self.scroll = min(self.scroll, maximum)
        table_capacity = max(1, self.body_height-1)
        if self.table_index < self.table_scroll:
            self.table_scroll = self.table_index
        elif self.table_index >= self.table_scroll+table_capacity:
            self.table_scroll = self.table_index-table_capacity+1

    def footer(self):
        if self.top:
            hints = [('j/k', 'move cursor'), ('f/b', 'scroll'), ('1', 'sort by total'),
                     ('2', 'sort by own'), ('/', 'filter'), ('r', 'reset'),
                     ('tab', 'switch view'), ('q', 'quit')]
        else:
            hints = [('hjkl', 'move cursor'), ('f/b', 'scroll'), ('enter/esc', 'zoom'),
                     ('/', 'search'), ('#', 'search like cursor')]
            if self.pattern is not None:
                hints.append(('n/N', 'next/prev search'))
            hints += [('r', 'reset'), ('tab', 'switch view'), ('q', 'quit')]
        spans = [(' ', DEFAULT)]
        for i, (key, meaning) in enumerate(hints):
            spans += [('[', DEFAULT), (key, ACCENT), (': '+meaning+']', DEFAULT), (' ', DEFAULT)]
        return spans

    def render(self, width, height):
        self.width, self.height = max(1, width), max(1, height)
        width, height = self.width, self.height
        panels = self.panels()
        panel_height = sum(1+len(lines) for _, lines in panels)
        footer_height = min(2, height)
        header_height = min(3, max(0, height-footer_height-panel_height))
        self.body_y = header_height
        self.body_height = max(0, height-header_height-footer_height-panel_height)
        self.place_frames()
        self.ensure_cursor()
        canvas = Canvas(width, height)
        if header_height:
            canvas.border(0)
        if header_height > 1:
            graph = '[Flamegraph]' if not self.top else 'Flamegraph'
            top = '[Top]' if self.top else 'Top'
            spans = [(' ', DEFAULT), (graph, BOLD if self.top else ACCENT),
                     (' | ', DEFAULT), (top, ACCENT if self.top else BOLD), (' ', DEFAULT)]
            canvas.spans(0, 1, spans)
            center_x, center_width = 20, max(0, width-36)
            cx = center_x + max(0, center_width//2-display_width(self.title)//2)
            canvas.text(cx, 1, self.title, BOLD, limit=max(0, width-16-cx))
            canvas.text(max(0, width-16), 1, VERSION.replace(' 0.', ' v0.'), BOLD)
        if header_height > 2:
            canvas.border(2)
        if self.top:
            self.draw_table(canvas)
        else:
            self.draw_flames(canvas)
        y = header_height + self.body_height
        for title, lines in panels:
            canvas.border(y, title)
            for i, line in enumerate(lines):
                canvas.text(0, y+1+i, line)
            y += 1+len(lines)
        self.cursor = None
        if self.editing and panels:
            y = header_height+self.body_height+1
            logical_cursor = display_width(self.input_text[:self.input_cursor])
            if logical_cursor < self.input_scroll:
                self.input_scroll = logical_cursor
            elif logical_cursor-self.input_scroll >= width:
                self.input_scroll = logical_cursor-width+1
            visible = ''
            skip = 0
            for char, cw, _, _ in glyphs(self.input_text):
                if skip >= self.input_scroll:
                    visible += char
                skip += cw
            canvas.text(0, y, visible)
            self.cursor = (max(0, logical_cursor-self.input_scroll), y)
        if footer_height == 2:
            canvas.border(height-2)
        if footer_height:
            spans = self.footer()
            size = sum(display_width(text) for text, _ in spans)
            x = max(0, width//2-size//2)
            canvas.spans(x, height-1, spans)
        return canvas

    def draw_flames(self, canvas):
        for node in self.order:
            y = self.body_y + node.depth-self.scroll
            if not self.body_y <= y < self.body_y+self.body_height:
                continue
            x, width = self.placed[node]
            highlights = self.matches.get(node.name, ()) if node is not self.profile.root else ()
            bg = MATCH_BG if highlights else heat_color(node.path)
            if node in self.ancestors:
                bg = tuple(int(c*.4) for c in bg)
            if node is self.selected:
                bg = SELECT_BG
            style = (text_color(bg), bg, False, False)
            canvas.fill(x, y, width, style)
            shifted = [(a+1, b+1) for a, b in highlights]
            canvas.text(x, y, ' '+node.name, style, limit=width, highlights=shifted)

    def draw_table(self, canvas):
        if not self.body_height:
            return
        total = self.profile.root.count
        fields = [(name, f'{count} ({percentage(count,total)}%)',
                   f'{own} ({percentage(own,total)}%)') for name, count, own in self.rows]
        col1 = max((display_width(a)+2 for _, a, _ in fields), default=0)
        col2 = max((display_width(b)+2 for _, _, b in fields), default=0)
        x2 = col1 + 1
        x3 = col1 + col2 + 2
        header_style = (None, None, True, True)
        canvas.fill(0, self.body_y, self.width, header_style)
        canvas.text(0, self.body_y, 'Total' + ('' if self.sort_own else ' [▼]'), header_style, col1)
        canvas.text(x2, self.body_y, 'Own' + (' [▼]' if self.sort_own else ''), header_style, col2)
        canvas.text(x3, self.body_y, 'Name', header_style)
        for y in range(1, self.body_height):
            idx = self.table_scroll+y-1
            if idx >= len(fields):
                break
            name, count, own = fields[idx]
            style = (None, ROW_BG if idx == self.table_index else None, False, False)
            canvas.fill(0, self.body_y+y, self.width, style)
            canvas.text(0, self.body_y+y, count, style, col1)
            canvas.text(x2, self.body_y+y, own, style, col2)
            canvas.text(x3, self.body_y+y, name, style, highlights=self.matches.get(name, ()))

    def pick_level(self, depth):
        candidates = self.levels.get(depth, [])
        if candidates:
            self.selected = max(enumerate(candidates), key=lambda p: (p[1].count, p[0]))[1]

    def scroll_graph(self, offset):
        maximum = max(0, self.max_depth+1-max(1, self.body_height))
        new_scroll = min(max(0, offset), maximum)
        if new_scroll == self.scroll:
            return
        self.scroll = new_scroll
        if not self.scroll <= self.selected.depth < self.scroll+self.body_height:
            self.pick_level(self.scroll)
        self.info = None

    def edit_key(self, key):
        text, pos = self.input_text, self.input_cursor
        if key == 'ESC':
            self.editing = False
            return
        if key == 'ENTER':
            self.editing = False
            self.set_pattern(text)
            return
        if key in ('LEFT', 'C-b'):
            pos = max(0, pos-1)
        elif key in ('RIGHT', 'C-f'):
            pos = min(len(text), pos+1)
        elif key in ('HOME', 'C-a'):
            pos = 0
        elif key in ('END', 'C-e'):
            pos = len(text)
        elif key in ('BACKSPACE', 'C-h'):
            if pos:
                text = text[:pos-1]+text[pos:]
                pos -= 1
        elif key in ('DELETE', 'C-d'):
            text = text[:pos]+text[pos+1:]
        elif key == 'C-u':
            text, pos = text[pos:], 0
        elif key == 'C-k':
            text = text[:pos]
        elif key in ('C-w', 'ALT-BACKSPACE'):
            start = pos
            while start and text[start-1].isspace():
                start -= 1
            while start and not text[start-1].isspace():
                start -= 1
            text, pos = text[:start]+text[pos:], start
        elif key in ('ALT-b', 'C-LEFT'):
            while pos and text[pos-1].isspace():
                pos -= 1
            while pos and not text[pos-1].isspace():
                pos -= 1
        elif key in ('ALT-f', 'C-RIGHT'):
            while pos < len(text) and text[pos].isspace():
                pos += 1
            while pos < len(text) and not text[pos].isspace():
                pos += 1
        elif len(key) == 1 and key.isprintable():
            text = text[:pos]+key+text[pos:]
            pos += 1
        self.input_text, self.input_cursor = text, pos

    def key(self, key):
        if self.editing:
            self.edit_key(key)
            return
        if key in ('q', 'C-c'):
            self.keep_running = False
            return
        if key == '/':
            self.editing = True
            self.input_text = ''
            self.input_cursor = self.input_scroll = 0
            self.info = None
            return
        if key == 'TAB':
            self.top = not self.top
            self.info = None
            return
        if key == '?':
            self.debug = not self.debug
            return
        if key == 'r':
            self.reset()
            return
        if key == 'ESC':
            if self.zoom is not None:
                self.zoom = None
                self.info = None
            return
        if key.startswith('C-') and len(key) == 3:
            key = key[-1]
        if self.top:
            if key in ('j', 'DOWN'):
                new = min(self.table_index+1, max(0,len(self.rows)-1))
                if new != self.table_index:
                    self.info = None
                self.table_index = new
            elif key in ('k', 'UP'):
                new = max(0, self.table_index-1)
                if new != self.table_index:
                    self.info = None
                self.table_index = new
            elif key in ('f', 'b'):
                delta = max(1,self.body_height) * (1 if key == 'f' else -1)
                self.table_scroll = min(max(0,self.table_scroll+delta), max(0,len(self.rows)-1))
                self.table_index = self.table_scroll
                self.info = None
            elif key in ('1', '2'):
                self.sort_own = key == '2'
                self.refresh_rows()
                self.info = None
            elif key == 'ENTER' and self.rows:
                name = self.rows[self.table_index][0]
                self.set_pattern('^' + regex_escape(name) + '$')
                self.top = False
            return
        if key in ('j', 'DOWN'):
            children = [n for n in self.selected.children if n in self.placed]
            if children:
                self.selected = max(enumerate(children), key=lambda p: (p[1].count,p[0]))[1]
                self.info = None
        elif key in ('k', 'UP'):
            if self.selected.parent is not None:
                self.selected = self.selected.parent
                self.info = None
        elif key in ('h', 'LEFT', 'l', 'RIGHT'):
            row = self.levels.get(self.selected.depth, [])
            if self.selected in row:
                idx = row.index(self.selected)
                idx += -1 if key in ('h','LEFT') else 1
                if 0 <= idx < len(row):
                    self.selected = row[idx]
                    self.info = None
        elif key in ('f', 'b'):
            self.scroll_graph(self.scroll+self.body_height*(1 if key=='f' else -1))
        elif key == 'g':
            self.scroll_graph(0)
        elif key == 'G':
            self.scroll_graph(self.max_depth+1)
        elif key == 'ENTER':
            if self.selected is self.profile.root:
                self.zoom = None
            else:
                self.zoom = self.selected
            self.info = None
        elif key == '#':
            if self.selected is not self.profile.root:
                self.set_pattern('^'+regex_escape(self.selected.name)+'$')
        elif key in ('n', 'N') and self.pattern is not None:
            index = self.order.index(self.selected) if self.selected in self.order else 0
            candidates = self.order[index+1:] if key == 'n' else list(reversed(self.order[:index]))
            for node in candidates:
                if node is not self.profile.root and self.matches.get(node.name):
                    self.selected = node
                    self.info = None
                    break


def ansi_style(style):
    fg, bg, bold, reverse = style
    codes = ['0']
    if bold:
        codes.append('1')
    if reverse:
        codes.append('7')
    for color, base in ((fg,38),(bg,48)):
        if isinstance(color, tuple):
            codes += [str(base), '2', *(str(n) for n in color)]
        elif color is not None:
            codes += [str(base), '5', str(color)]
    return '\x1b['+';'.join(codes)+'m'


class Terminal:
    def __init__(self, fd):
        self.fd = fd
        self.old_mode = None
        self.last = None
        self.size = None

    def dimensions(self):
        try:
            size = os.get_terminal_size(self.fd)
            return max(1,size.columns), max(1,size.lines)
        except OSError:
            return 80,24

    def write(self, text):
        raw = text.encode('utf-8', 'replace')
        while raw:
            count = os.write(2, raw)
            raw = raw[count:]

    def enter(self):
        self.old_mode = termios.tcgetattr(self.fd)
        mode = termios.tcgetattr(self.fd)
        mode[0] &= ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
        mode[1] &= ~termios.OPOST
        mode[2] |= termios.CS8
        mode[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
        mode[6][termios.VMIN] = 1
        mode[6][termios.VTIME] = 0
        termios.tcsetattr(self.fd, termios.TCSANOW, mode)
        self.write('\x1b[?1049h\x1b[?25l\x1b[?7l\x1b[2J')

    def leave(self):
        try:
            self.write('\x1b[0m\x1b[?7h\x1b[?1049l\x1b[?25h')
        finally:
            if self.old_mode is not None:
                termios.tcsetattr(self.fd, termios.TCSANOW, self.old_mode)

    def draw(self, canvas, cursor):
        chunks = []
        dims = (canvas.width, canvas.height)
        if dims != self.size:
            self.last = None
            self.size = dims
            chunks.append('\x1b[2J')
        current_style = None
        for y, row in enumerate(canvas.rows):
            if self.last is not None and self.last[y] == row:
                continue
            chunks.append(f'\x1b[{y+1};1H')
            for char, style in row:
                if not char:
                    continue
                if style != current_style:
                    chunks.append(ansi_style(style))
                    current_style = style
                chunks.append(char)
        chunks.append('\x1b[0m')
        if cursor is None:
            chunks.append('\x1b[?25l')
        else:
            x, y = cursor
            chunks.append(f'\x1b[{y+1};{x+1}H\x1b[?25h')
        self.write(''.join(chunks))
        self.last = canvas.rows


ESCAPES = {
    b'\x1b[A': 'UP', b'\x1b[B': 'DOWN', b'\x1b[C': 'RIGHT', b'\x1b[D': 'LEFT',
    b'\x1bOA': 'UP', b'\x1bOB': 'DOWN', b'\x1bOC': 'RIGHT', b'\x1bOD': 'LEFT',
    b'\x1b[H': 'HOME', b'\x1b[F': 'END', b'\x1bOH': 'HOME', b'\x1bOF': 'END',
    b'\x1b[1~': 'HOME', b'\x1b[4~': 'END', b'\x1b[7~': 'HOME', b'\x1b[8~': 'END',
    b'\x1b[3~': 'DELETE', b'\x1b[2~': 'INSERT', b'\x1b[5~': 'PAGEUP', b'\x1b[6~': 'PAGEDOWN',
    b'\x1b[Z': 'BACKTAB', b'\x1b[1;5D': 'C-LEFT', b'\x1b[1;5C': 'C-RIGHT',
    b'\x1bb': 'ALT-b', b'\x1bf': 'ALT-f', b'\x1b\x7f': 'ALT-BACKSPACE',
}


def parse_keys(data, flush=False):
    keys = []
    while data:
        b = data[0]
        if b == 27:
            matched = next((seq for seq in ESCAPES if data.startswith(seq)), None)
            if matched is not None:
                keys.append(ESCAPES[matched])
                data = data[len(matched):]
                continue
            if not flush and any(seq.startswith(data) for seq in ESCAPES):
                break
            if len(data) > 1 and data[1] in (ord('['), ord('O')):
                m = re.match(rb'\x1b(?:\[[0-9;<?]*[a-zA-Z~]|O.)', data)
                if m:
                    data = data[m.end():]
                    continue
                if not flush:
                    break
            keys.append('ESC')
            data = data[1:]
        elif b in (10,13):
            keys.append('ENTER')
            data = data[1:]
        elif b == 9:
            keys.append('TAB')
            data = data[1:]
        elif b in (8,127):
            keys.append('BACKSPACE')
            data = data[1:]
        elif b < 32:
            keys.append('C-'+chr(96+b))
            data = data[1:]
        else:
            length = 1 if b < 128 else (2 if b < 224 else (3 if b < 240 else 4))
            if len(data) < length and not flush:
                break
            try:
                char = data[:length].decode('utf-8')
                keys.append(char)
            except UnicodeDecodeError:
                pass
            data = data[length:]
    return keys, data


def run_ui(viewer):
    try:
        fd = os.open('/dev/tty', os.O_RDWR | os.O_NOCTTY)
    except OSError:
        return 'Os { code: 11, kind: WouldBlock, message: "Resource temporarily unavailable" }'
    terminal = Terminal(fd)
    pending = b''
    interrupted = [False]

    def resize(signum, frame):
        interrupted[0] = True

    signal.signal(signal.SIGWINCH, resize)
    try:
        terminal.enter()
        dirty = True
        previous_dimensions = None
        last_debug = time.monotonic()
        while viewer.keep_running:
            dimensions = terminal.dimensions()
            if dimensions != previous_dimensions or interrupted[0]:
                dirty = True
                previous_dimensions = dimensions
                interrupted[0] = False
            if viewer.debug and not viewer.editing and time.monotonic()-last_debug > .5:
                dirty = True
                last_debug = time.monotonic()
            if dirty:
                canvas = viewer.render(*dimensions)
                terminal.draw(canvas, viewer.cursor)
                dirty = False
            ready, _, _ = select.select([fd], [], [], .04 if pending else .10)
            if ready:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                pending += chunk
                keys, pending = parse_keys(pending)
            else:
                keys, pending = parse_keys(pending, True)
            for key in keys:
                viewer.key(key)
                # Geometry and viewport updates also apply between characters
                # from one read (for example, pasted navigation commands).
                viewer.render(*dimensions)
                dirty = True
                if not viewer.keep_running:
                    break
    except (OSError, termios.error) as e:
        return rust_os_error(e)
    except KeyboardInterrupt:
        pass
    finally:
        terminal.leave()
        os.close(fd)
    return None


def main():
    filename, flags = arguments(sys.argv)
    text = read_profile(filename)
    profile = Profile(text, '--sorted' in flags)
    viewer = Viewer(profile, filename if filename is not None else 'stdin', '--debug' in flags)
    error = run_ui(viewer)
    if '--echo' in flags:
        sys.stdout.write(text + '\n')
        sys.stdout.flush()
    if error:
        sys.stderr.write('Error: '+error+'\n')
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
