def cells(s):
 screen=capture(s,True); rows=[];fg=bg=None;bold=rev=False
 for line in screen.splitlines():
  row=[]
  for i,p in enumerate(re.split(r'\x1b\[([\d;]*)m',line)):
   if i%2:
    nums=list(map(int,p.split(';'))) if p else [0];j=0
    while j<len(nums):
     n=nums[j]
     if n==0:fg=bg=None;bold=rev=False
     elif n==1:bold=True
     elif n==7:rev=True
     elif n in (22,):bold=False
     elif n in (27,):rev=False
     elif n==39:fg=None
     elif n==49:bg=None
     elif n in (38,48):
      if nums[j+1]==2:c=tuple(nums[j+2:j+5]);j+=4
      elif nums[j+1]==5:c=nums[j+2];j+=2
      if n==38:fg=c
      else:bg=c
     j+=1
   else:
    for c,w,_,_ in glyphs(p):
     row.append((c,fg,bg,bold,rev))
     if w==2:row.append(('',fg,bg,bold,rev))
  rows.append(row)
 return rows

def compare(label,styles=False):
 a=capture('cmpref');b=capture('cmpnew')
 if a!=b:
  print('\nDIFF',label)
  for line in difflib.unified_diff(a.splitlines(),b.splitlines(),fromfile='ref',tofile='new',lineterm=''):print(line)
 elif not styles:print('OK',label)
 if styles:
  aa=cells('cmpref');bb=cells('cmpnew');diffs=[]
  for y,(ar,br) in enumerate(zip(aa,bb)):
   for x in range(max(len(ar),len(br))):
    av=ar[x] if x<len(ar) else (' ',None,None,False,False);bv=br[x] if x<len(br) else (' ',None,None,False,False)
    if av!=bv:diffs.append((x,y,av,bv))
  print('STYLES',label,len(diffs),'differences',diffs[:8])

def run(args,keys,w=100,h=30,styles=True):
 launch('cmpref','./.probe/reference/executable',args,w,h)
 launch('cmpnew','./executable',args,w,h)
 compare('start '+args,styles)
 for key in keys:
  send('cmpref',key);send('cmpnew',key);time.sleep(.09)
  compare(repr(key),styles)
